final notifications = FlutterLocalNotificationsPlugin();

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await notifications.initialize(const InitializationSettings(android: AndroidInitializationSettings('@mipmap/ic_launcher')));
  runApp(const DayboardApp());
}

class DayboardApp extends StatefulWidget { const DayboardApp({super.key}); @override State<DayboardApp> createState() => _DayboardAppState(); }
class _DayboardAppState extends State<DayboardApp> {
  final storage = PlannerStorage(); PlannerState state = PlannerState(); DayTheme appTheme = DayTheme.cream; bool ready = false;
  @override void initState() { super.initState(); _load(); }
  Future<void> _load() async { state = await storage.load(); appTheme = await storage.loadTheme(); setState(() => ready = true); }
  @override Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner: false, title: 'Dayboard', theme: dayboardTheme(), home: ready ? PlannerHome(state: state, storage: storage, appTheme: appTheme, onThemeChanged: (theme) { setState(() => appTheme = theme); storage.saveTheme(theme); }) : const Scaffold(body: Center(child: CircularProgressIndicator())));
}

